type Figure={el:()=>React.ReactElement;captionHe:string};
const schematic="סכמה מקורית ללא קנה מידה. ";
export const CANCER_FIGURES:Record<string,Figure>={
 'ca-tumor-types':{el:TumorTypes,captionHe:schematic+'הסיווג לפי רקמת המוצא והקירוב של 80% ממקרי המוות מקרצינומות נלקחו מהיחידה; אין כאן התפלגות של שכיחות אבחנות.'},
 'ca-monoclonality':{el:Monoclonality,captionHe:schematic+'פסיפס של איזופורמי G6PD ברקמה תקינה לעומת מיומות שכל אחת מבטאת גרסה אחת. מסילות ג׳ל סכמטיות, ללא ייחוס עוצמה או כיוון נדידה ניסויי. המוצא החד־שבטי נתמך בשילוב ראיות.'},
 'ca-hallmarks':{el:Hallmarks,captionHe:schematic+'שמונה היכולות מטבלת היחידה, עם תגיות נושאי הקורס, ושני מאפיינים מאפשרים. ההערה על Hanahan 2022 נפרדת ואינה מנסה למנות את כל הרחבות המסגרת.'},
 'ca-transformation-foci':{el:Transformation,captionHe:schematic+'שכבה יחידה לעומת מוקד תאים וגדילה ללא עגינה. במוטנט רגיש לטמפרטורה הפנוטיפ הפיך, ומעיד שפעילות Src דרושה לשימורו. אין כאן פרוטוקול ניסויי או טמפרטורות עבודה.'},
 'ca-acute-vs-slow-retrovirus':{el:Retrovirus,captionHe:schematic+'השוואה עקרונית בין נשיאת אונקוגן לבין הפעלת גן תאי בהחדרה. נגיפים חריפים לרוב פגומים ודורשים עוזר; RSV הוא חריג. השיבוטיות והזמנים הם דפוס המודל ההיסטורי של היחידה.'},
 'ca-dna-virus-rb-p53':{el:DnaVirus,captionHe:schematic+'LT של SV40 קושר pRb ו־p53; E7 של HPV משבית את ציר pRb ו־E6 מגייס E6AP לפירוק p53. שיבוש E2 בהשתלבות עשוי להגביר E6/E7; אין הכרח להשתלבות בכל גידול הקשור ל־HPV.'},
 'ca-transfection-assay':{el:Transfection,captionHe:schematic+'ההיגיון ההיסטורי של זיהוי HRAS באמצעות מוקדים והעברת DNA חוזרת. Alu מזהה מקטע אנושי ברקע תאי העכבר. תאי NIH 3T3 כבר מונצחים והמבחן אינו מזהה את כלל מנגנוני הסרטן.'},
 'ca-oncogene-activation':{el:Activation,captionHe:schematic+'שלוש משפחות שינוי: פעילות החלבון, כמותו, ואיחוי או שינוי בקרה. מספר העותקים המצויר ב־DM/HSR להמחשה בלבד. בבורקיט MYC אינו חלבון איחוי.'},
 'ca-oncogene-cooperation':{el:Cooperation,captionHe:schematic+'תוצאות תרביות לפי היחידה. עקומות העכברים סינתטיות ללא יחידות זמן או נתונים ניסויים: רק המחשה ששילוב myc ו־ras מאיץ הופעת גידולים. נוסחאות ההמחשה מתועדות בכרטיס הידע.'},
 'ca-signal-autonomy':{el:SignalAutonomy,captionHe:schematic+'ליגנד עצמי, קולטן/קינאז פעיל ושינויים במורד הזרם מספקים שלוש רמות של אוטונומיה. ענפי Ras–MAPK ו־PI3K–Akt מוצגים בפישוט; Ras יכול להפעיל גם PI3K. EML4–ALK הוא קינאז מאוחה תוך־תאי.'},
 'ca-wnt-apc':{el:Wnt,captionHe:schematic+'הפסקת הזרחון והפירוק מייצבת β-קטנין ומאפשרת שעתוק עם TCF. קומפלקס ההרס מעוכב ומתארגן מחדש באיתות Wnt; האיור אינו דורש פירוק מוחלט שלו. inset הכוכית מציג את כיוון ההתמיינות בלבד.'},
 'ca-cell-fusion':{el:Fusion,captionHe:schematic+'ניסויי כלאיים תומכים בקיום מדכאי גידול. דיכוי באיחוי, אובדן הדיכוי עם כרומוזומים והצלה בכרומוזום יחיד תלויים בקו התאים; מספר הכרומוזומים המצויר אינו קריוטיפ.'},
 'ca-loh-mechanisms':{el:Loh,captionHe:schematic+'מספר העותקים מתייחס ללוקוס הנבדק. רקומבינציה מיטוטית יוצרת LOH דיסטלי באתר המתאים; המרה גנית מקומית. מוטציה נקודתית ומתילציה יכולות להשבית את האלל השני תוך שמירת הטרוזיגוטיות בסמני DNA.'},
 'ca-restriction-point':{el:Restriction,captionHe:schematic+'המודל הדידקטי של היחידה: ציקלין D–CDK4/6 מתחיל את שינוי מצב pRb ומשוב E2F–ציקלין E–CDK2 מייצב כניסה למחזור. זרחון וגורמי גדילה אינם השפעה כמותית שנמדדה כאן.'},
 'ca-rb-pathway-hits':{el:RbHits,captionHe:schematic+'חמש הפגיעות מובילות לאובדן ריסון E2F. במקרה של אובדן pRb אין צורך ב־pRb מזורחן כדי לשחרר E2F. ״מכה אחת למסלול״ הוא דפוס שכיח עם חריגים; p16 גבוה לבדו אינו אבחנה.'},
 'ca-apoptosis-necrosis':{el:ApoptosisNecrosis,captionHe:schematic+'מורפולוגיות קלאסיות: אריזה ופינוי לעומת התנפחות וקריעת קרום. אין כאן טענה שכל מוות בעל מראה נקרוטי אינו מוסדר או שאפופטוזיס לעולם אינה מלווה בדלקת.'},
 'ca-p53-decisions':{el:P53Decisions,captionHe:schematic+'עקות שונות מייצבות p53 ומאפשרות תוצאות תלויות הקשר. inset הטטרמר ממחיש פגיעה שלילית־דומיננטית אפשרית; אינו קובע שכל מוטנט או כל טטרמר מעורב חסר פעילות לחלוטין.'},
 'ca-apoptosis-pathways':{el:ApoptosisPaths,captionHe:schematic+'מסלול Fas/TRAIL–FADD–DISC וזרוע BH3–Bax/Bak–MOMP מתכנסים לקספאזות מבצעות. אפופטוזום מכיל שבעה Apaf-1; SMAC מסיר עיכוב XIAP ו־tBid מחבר בין המסלולים. מסלול TNFR1 אינו מוצג כאילו זהה ל־DISC הממברנלי.'},
 'ca-bcl2-translocation':{el:Bcl2,captionHe:schematic+'BCL2 ליד אנהנסר IGH מגביר הישרדות בתאי B. התרבות ושיתוף עם MYC נבדלים מהישרדות לבדה. ונטוקלקס תופס את חריץ BH3 של Bcl-2; צורת החלבון להמחשת כיס בלבד.'},
 'ca-degradation-failures':{el:DegradationFailures,captionHe:schematic+'השלכות אובדן E3, עודף E3 ופגיעה בדגרון לפי דוגמאות היחידה. את β-קטנין מזהה β-TrCP ולא FBXW7.'},
 'ca-fbxw7-substrates':{el:Fbxw7,captionHe:schematic+'דימר FBXW7 וכיס WD40 מוצגים ללא קנה מידה אטומי. זרחון מכין ו־GSK3 הם דפוס נפוץ ולא דרישה זהה לכל מצע. מצעיו והציר הנפרד p27–Skp2/Cks1 נשמרו לפי היחידה.'},
 'ca-initiation-promotion':{el:InitiationPromotion,captionHe:'נתוני ההמחשה המספרית הם בדיוק נתוני שאלת skin-protocol: ‏0.1, 0.2, 12, 0.3, 11, 2 פפילומות לעכבר. אורך העמודה מחושב ביחס ל־12. רצפי הסימנים מציגים סדר ותדירות ולא משחזרים את כל החשיפות.'},
 'ca-colon-sequence':{el:ColonSequence,captionHe:schematic+'התאמה לטבלת היחידה: APC מוקדם, KRAS בהתרחבות האדנומה, 18q/SMAD4 במעבר לקרצינומה ו־TP53 בסביבת שלב הקרצינומה. הצבת שני השינויים המאוחרים באותו מעבר אינה קובעת סדר חובה ביניהם.'},
 'ca-telomere-crisis':{el:Telomeres,captionHe:schematic+'הקו הכחול מסיים בהזדקנות; המקווקו הוא מסלול עקיפה באובדן מחסומים. הקו הירוק מייצג שורדים נדירים עם תחזוקת טלומרים. אלה צירים יחסיים ללא אורך טלומרים או מספר חלוקות מדוד.'},
 'ca-tumor-microenvironment':{el:Microenvironment,captionHe:schematic+'כל סוג תא והמטריצה נבדלים בצורתם. רשימות האיתות ההדדי הן דוגמאות מהיחידה ולא קשר חד־חד־ערכי בין ליגנד לסוג תא. CAFs ו־TAMs הם אוכלוסיות הטרוגניות.'},
 'ca-angiogenic-switch':{el:Angiogenesis,captionHe:schematic+'במודל RIP-Tag היפרפלזיה אינה מבטיחה גיוס כלי דם. טווח דיפוזיית החמצן 100–200 μm לקוח מהיחידה; הוא אינו סף אחיד לכל רקמה. נרמול הוא אפשרות תלויה בהקשר, לא תוצאה מובטחת.'},
 'ca-metastatic-cascade':{el:Metastasis,captionHe:'המפל סכמטי; שיעורי Luzzi מהיחידה מסומנים בקירוב על ציר log10 משותף: ‏80%, ‏2%, ‏0.02% מתוך אוכלוסיית המקור. ההזרקה הניסויית עקפה את הפלישה והכניסה מהגידול הראשוני. התבססות היא צוואר הבקבוק המרכזי במודל זה.'},
 'ca-emt':{el:Emt,captionHe:schematic+'EMT רציף וחלקי יכול להיות הפיך. MET ופלישה קבוצתית מוצגים בלי לטעון ש־EMT מלא נדרש בכל גרורה. סמנים בודדים אינם מגדירים לבדם את כל מצב התא.'},
 'ca-tumor-antigens':{el:Antigens,captionHe:schematic+'TSA לעומת TAA כפי שסווגו ביחידה; הכרת CD8 תלויה בפפטיד וב־MHC-I. הסבילות ל־TAA משתנה, במיוחד באנטיגני סרטן־אשכים, ולכן אינה מתוארת כאחידה או מוחלטת.'},
 'ca-immunoediting':{el:Immunoediting,captionHe:schematic+'שלושת שלבי העריכה וניסוי ההשתלה: כ־40% דחייה במקבלי WT לגידולים ממקור Rag2−/−, לעומת 0% למקור WT בנתוני היחידה. רוחב העמודה מחושב מהאחוז, לא ממספר גידולים שהומצא.'},
 'ca-checkpoints':{el:Checkpoints,captionHe:schematic+'CTLA-4 מתחרה ב־CD28 על B7 בשלב ההפעלה; PD-1 מגיב ל־PD-L1 ברקמה. IFN-γ יכול להגביר את הליגנד במנגנון הסתגלותי. נוגדן כתום מסמל חסימת קישור; השפעותיהם אינן מוגבלות בלעדית לשני המקומות המצוירים.'},
 'ca-methylation-landscape':{el:Methylation,captionHe:schematic+'היפומתילציה בחזרות לצד היפרמתילציה מקומית באיי CpG; מספר ה־CpGs המצויר אינו מדידה או שיעור. מתילציה קשורה להשתקה אך הוכחת סיבתיות דורשת ראיות נוספות.'},
 'ca-idh-2hg':{el:Idh,captionHe:schematic+'IDH מוטנטי יוצר 2-HG מ־α-KG; עיכוב TET ו־JmjC מחבר מטבוליזם לאפיגנום. איבוסידניב הוא דוגמה למעכב IDH1 מוטנטי; אין לייחס לו עיכוב IDH2 באופן כללי.'},
};
